using System;
using Framework.AI.Actions;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// エージェントの行動実行システムを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class AgentActionControllerTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 50;

        /// <summary>
        /// テスト用の行動実装。
        /// </summary>
        private sealed class TestAction :
            IAgentAction<string, int>
        {
            /// <summary>行動識別子。</summary>
            public string Id { get; }

            /// <summary>行動実行設定。</summary>
            public AgentActionSettings Settings { get; }

            /// <summary>行動開始を許可するか。</summary>
            public bool AllowEnter = true;

            /// <summary>行動開始回数。</summary>
            public int EnterCount;

            /// <summary>行動更新回数。</summary>
            public int TickCount;

            /// <summary>行動終了回数。</summary>
            public int ExitCount;

            /// <summary>最後に受け取った実行情報。</summary>
            public int LastContext;

            /// <summary>最後に受け取った経過秒数。</summary>
            public float LastDeltaTime;

            /// <summary>最後の行動終了理由。</summary>
            public AgentActionExitReason LastExitReason;

            /// <summary>次回更新時に返す行動結果。</summary>
            public AgentActionStatus NextStatus =
                AgentActionStatus.Running;

            /// <summary>開始時に例外を発生させるか。</summary>
            public bool ThrowOnEnter;

            /// <summary>更新時に例外を発生させるか。</summary>
            public bool ThrowOnTick;

            /// <summary>終了時に例外を発生させるか。</summary>
            public bool ThrowOnExit;

            /// <summary>テスト用行動を生成する。</summary>
            /// <param name="id">行動識別子</param>
            /// <param name="settings">行動実行設定</param>
            public TestAction(
                string id,
                AgentActionSettings settings = null)
            {
                Id = id;
                Settings = settings ??
                    new AgentActionSettings();
            }

            /// <summary>行動開始条件を確認する。</summary>
            /// <param name="context">実行情報</param>
            /// <returns>開始可能な場合はtrue</returns>
            public bool CanEnter(int context)
            {
                return AllowEnter;
            }

            /// <summary>行動開始処理を記録する。</summary>
            /// <param name="context">実行情報</param>
            public void Enter(int context)
            {
                EnterCount++;
                LastContext = context;

                if (ThrowOnEnter)
                {
                    throw new InvalidOperationException(
                        "テスト用開始例外");
                }
            }

            /// <summary>行動更新処理を記録する。</summary>
            /// <param name="context">実行情報</param>
            /// <param name="deltaTime">経過秒数</param>
            /// <returns>設定された行動結果</returns>
            public AgentActionStatus Tick(
                int context,
                float deltaTime)
            {
                TickCount++;
                LastContext = context;
                LastDeltaTime = deltaTime;

                if (ThrowOnTick)
                {
                    throw new InvalidOperationException(
                        "テスト用更新例外");
                }

                return NextStatus;
            }

            /// <summary>行動終了処理を記録する。</summary>
            /// <param name="context">実行情報</param>
            /// <param name="reason">終了理由</param>
            public void Exit(
                int context,
                AgentActionExitReason reason)
            {
                ExitCount++;
                LastContext = context;
                LastExitReason = reason;

                if (ThrowOnExit)
                {
                    throw new InvalidOperationException(
                        "テスト用終了例外");
                }
            }
        }

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestRegistration();
                TestExecution();
                TestCompletion();
                TestTransition();
                TestCooldown();
                TestPauseAndReset();
                TestSafety();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【AgentAction テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// 行動設定と登録処理を検証する。
        /// </summary>
        private void TestRegistration()
        {
            var settings =
                new AgentActionSettings(1f, 2f, false);

            bool settingsPassed =
                settings.MinimumDuration == 1f &&
                settings.Cooldown == 2f &&
                !settings.CanInterrupt;
            Debug.Assert(settingsPassed, "行動設定の保持", this);
            Check(settingsPassed, "行動設定の保持");

            bool invalidPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                    new AgentActionSettings(-1f)) &&
                Throws<ArgumentOutOfRangeException>(() =>
                    new AgentActionSettings(
                        cooldown: float.NaN));
            Debug.Assert(invalidPassed, "不正時間設定の拒否", this);
            Check(invalidPassed, "不正時間設定の拒否");

            var controller =
                new AgentActionController<string, int>();

            bool initialPassed =
                controller.Count == 0 &&
                !controller.HasCurrentAction;
            Debug.Assert(initialPassed, "初期状態", this);
            Check(initialPassed, "初期状態");

            var action = new TestAction("Patrol");

            bool registerPassed =
                controller.TryRegister(action) &&
                controller.Count == 1 &&
                controller.HasAction("Patrol");
            Debug.Assert(registerPassed, "行動登録", this);
            Check(registerPassed, "行動登録");

            bool duplicatePassed =
                !controller.TryRegister(
                    new TestAction("Patrol")) &&
                controller.Count == 1;
            Debug.Assert(duplicatePassed, "重複行動登録の拒否", this);
            Check(duplicatePassed, "重複行動登録の拒否");

            bool missingPassed =
                !controller.HasAction("Unknown") &&
                !controller.TryUnregister("Unknown");
            Debug.Assert(missingPassed, "未登録行動の確認", this);
            Check(missingPassed, "未登録行動の確認");

            bool removePassed =
                controller.TryUnregister("Patrol") &&
                controller.Count == 0;
            Debug.Assert(removePassed, "行動登録解除", this);
            Check(removePassed, "行動登録解除");

            bool nullPassed =
                Throws<ArgumentNullException>(() =>
                    controller.TryRegister(null));
            Debug.Assert(nullPassed, "null行動登録の拒否", this);
            Check(nullPassed, "null行動登録の拒否");
        }

        /// <summary>
        /// 行動開始と更新処理を検証する。
        /// </summary>
        private void TestExecution()
        {
            var controller =
                new AgentActionController<string, int>();

            var action = new TestAction("Chase");

            controller.TryRegister(action);

            bool unknownPassed =
                !controller.TryStartAction("Unknown", 0);
            Debug.Assert(unknownPassed, "未登録行動の開始拒否", this);
            Check(unknownPassed, "未登録行動の開始拒否");

            action.AllowEnter = false;

            bool conditionPassed =
                !controller.TryStartAction("Chase", 0) &&
                action.EnterCount == 0;
            Debug.Assert(conditionPassed, "開始条件の確認", this);
            Check(conditionPassed, "開始条件の確認");

            action.AllowEnter = true;

            bool startPassed =
                controller.TryStartAction("Chase", 10) &&
                action.EnterCount == 1 &&
                action.LastContext == 10;
            Debug.Assert(startPassed, "行動開始処理", this);
            Check(startPassed, "行動開始処理");

            bool currentPassed =
                controller.HasCurrentAction &&
                controller.TryGetCurrentActionId(out var id) &&
                id == "Chase" &&
                ReferenceEquals(
                    controller.CurrentAction, action);
            Debug.Assert(currentPassed, "現在行動の取得", this);
            Check(currentPassed, "現在行動の取得");

            controller.Tick(20, 0.5f);

            bool tickPassed =
                action.TickCount == 1 &&
                action.LastContext == 20 &&
                action.LastDeltaTime == 0.5f;
            Debug.Assert(tickPassed, "行動更新処理", this);
            Check(tickPassed, "行動更新処理");

            bool timePassed =
                controller.ActionElapsedTime == 0.5d &&
                controller.TotalElapsedTime == 0.5d;
            Debug.Assert(timePassed, "行動経過時間", this);
            Check(timePassed, "行動経過時間");

            bool samePassed =
                controller.TryStartAction("Chase", 30) &&
                action.EnterCount == 1 &&
                controller.ActionElapsedTime == 0.5d;
            Debug.Assert(samePassed, "同一行動の再初期化防止", this);
            Check(samePassed, "同一行動の再初期化防止");

            bool removePassed =
                !controller.TryUnregister("Chase") &&
                controller.HasAction("Chase");
            Debug.Assert(removePassed, "実行中行動の登録解除防止", this);
            Check(removePassed, "実行中行動の登録解除防止");
        }

        /// <summary>
        /// 行動終了処理を検証する。
        /// </summary>
        private void TestCompletion()
        {
            var controller =
                new AgentActionController<string, int>();

            var action = new TestAction(
                "Action",
                new AgentActionSettings(5f));

            controller.TryRegister(action);
            controller.TryStartAction("Action", 0);

            action.NextStatus = AgentActionStatus.Succeeded;

            controller.Tick(1, 0.5f);

            bool successPassed =
                !controller.HasCurrentAction &&
                action.LastExitReason ==
                    AgentActionExitReason.Succeeded;
            Debug.Assert(successPassed, "行動成功による終了", this);
            Check(successPassed, "行動成功による終了");

            bool cleanupPassed =
                action.ExitCount == 1 &&
                action.LastContext == 1 &&
                controller.ActionElapsedTime == 0d;
            Debug.Assert(cleanupPassed, "正常終了後の状態初期化", this);
            Check(cleanupPassed, "正常終了後の状態初期化");

            controller.TryStartAction("Action", 0);

            action.NextStatus = AgentActionStatus.Failed;

            controller.Tick(2, 0.5f);

            bool failurePassed =
                !controller.HasCurrentAction &&
                action.LastExitReason ==
                    AgentActionExitReason.Failed;
            Debug.Assert(failurePassed, "行動失敗による終了", this);
            Check(failurePassed, "行動失敗による終了");

            controller.TryStartAction("Action", 0);

            bool stopPassed =
                controller.Stop(3) &&
                !controller.HasCurrentAction &&
                action.LastExitReason ==
                    AgentActionExitReason.Cancelled;
            Debug.Assert(stopPassed, "外部要求による停止", this);
            Check(stopPassed, "外部要求による停止");

            bool repeatPassed =
                !controller.Stop(0) &&
                action.ExitCount == 3;
            Debug.Assert(repeatPassed, "終了処理の重複防止", this);
            Check(repeatPassed, "終了処理の重複防止");

            bool emptyPassed =
                !controller.TryGetCurrentActionId(out var id) &&
                id == null;
            Debug.Assert(emptyPassed, "終了後の行動取得失敗", this);
            Check(emptyPassed, "終了後の行動取得失敗");
        }

        /// <summary>
        /// 行動切り替えと中断制限を検証する。
        /// </summary>
        private void TestTransition()
        {
            var controller =
                new AgentActionController<string, int>();

            var patrol = new TestAction(
                "Patrol",
                new AgentActionSettings(1f));

            var chase = new TestAction(
                "Chase",
                new AgentActionSettings(
                    canInterrupt: false));

            var escape = new TestAction("Escape");

            controller.TryRegister(patrol);
            controller.TryRegister(chase);
            controller.TryRegister(escape);

            controller.TryStartAction("Patrol", 0);

            bool minimumPassed =
                !controller.CanInterruptCurrent &&
                !controller.TryStartAction("Chase", 0);
            Debug.Assert(minimumPassed, "最低継続時間による中断制限", this);
            Check(minimumPassed, "最低継続時間による中断制限");

            controller.Tick(0, 1f);

            bool boundaryPassed =
                controller.CanInterruptCurrent;
            Debug.Assert(boundaryPassed, "最低継続時間の境界条件", this);
            Check(boundaryPassed, "最低継続時間の境界条件");

            chase.AllowEnter = false;

            bool preservePassed =
                !controller.TryStartAction("Chase", 0) &&
                ReferenceEquals(
                    controller.CurrentAction, patrol) &&
                patrol.ExitCount == 0;
            Debug.Assert(preservePassed, "開始条件不成立時の行動維持", this);
            Check(preservePassed, "開始条件不成立時の行動維持");

            chase.AllowEnter = true;

            bool switchPassed =
                controller.TryStartAction("Chase", 0) &&
                ReferenceEquals(
                    controller.CurrentAction, chase);
            Debug.Assert(switchPassed, "通常行動切り替え", this);
            Check(switchPassed, "通常行動切り替え");

            bool reasonPassed =
                patrol.ExitCount == 1 &&
                patrol.LastExitReason ==
                    AgentActionExitReason.Interrupted &&
                controller.ActionElapsedTime == 0d;
            Debug.Assert(reasonPassed, "切り替え時の終了処理", this);
            Check(reasonPassed, "切り替え時の終了処理");

            bool lockedPassed =
                !controller.CanInterruptCurrent &&
                !controller.TryStartAction("Escape", 0);
            Debug.Assert(lockedPassed, "中断禁止行動の維持", this);
            Check(lockedPassed, "中断禁止行動の維持");

            bool forcePassed =
                controller.TryStartAction(
                    "Escape", 0, true) &&
                chase.LastExitReason ==
                    AgentActionExitReason.Interrupted;
            Debug.Assert(forcePassed, "強制割り込み", this);
            Check(forcePassed, "強制割り込み");

            patrol.AllowEnter = false;

            bool forceConditionPassed =
                !controller.TryStartAction(
                    "Patrol", 0, true) &&
                ReferenceEquals(
                    controller.CurrentAction, escape);
            Debug.Assert(forceConditionPassed, "強制割り込み時の開始条件維持", this);
            Check(forceConditionPassed, "強制割り込み時の開始条件維持");
        }

        /// <summary>
        /// クールダウンの時間管理を検証する。
        /// </summary>
        private void TestCooldown()
        {
            var controller =
                new AgentActionController<string, int>();

            var action = new TestAction(
                "Action",
                new AgentActionSettings(cooldown: 2f));

            controller.TryRegister(action);
            controller.TryStartAction("Action", 0);
            controller.Stop(0);

            bool initialPassed =
                controller.IsOnCooldown("Action") &&
                controller.GetCooldownRemaining(
                    "Action") == 2f;
            Debug.Assert(initialPassed, "終了時のクールダウン開始", this);
            Check(initialPassed, "終了時のクールダウン開始");

            bool blockPassed =
                !controller.TryStartAction("Action", 0) &&
                !controller.TryStartAction("Action", 0, true);
            Debug.Assert(blockPassed, "クールダウン中の開始拒否", this);
            Check(blockPassed, "クールダウン中の開始拒否");

            controller.Tick(0, 0.5f);

            bool timePassed =
                controller.GetCooldownRemaining(
                    "Action") == 1.5f;
            Debug.Assert(timePassed, "非実行中のクールダウン更新", this);
            Check(timePassed, "非実行中のクールダウン更新");

            controller.Tick(0, 1.5f);

            bool boundaryPassed =
                !controller.IsOnCooldown("Action") &&
                controller.GetCooldownRemaining(
                    "Action") == 0f;
            Debug.Assert(boundaryPassed, "クールダウン終了境界", this);
            Check(boundaryPassed, "クールダウン終了境界");

            bool restartPassed =
                controller.TryStartAction("Action", 0) &&
                action.EnterCount == 2;
            Debug.Assert(restartPassed, "クールダウン後の再実行", this);
            Check(restartPassed, "クールダウン後の再実行");

            controller.Stop(0);
            controller.ClearCooldowns();

            bool clearPassed =
                !controller.IsOnCooldown("Action") &&
                controller.TryStartAction("Action", 0);
            Debug.Assert(clearPassed, "クールダウンの解除", this);
            Check(clearPassed, "クールダウンの解除");
        }

        /// <summary>
        /// 一時停止と実行状態の初期化を検証する。
        /// </summary>
        private void TestPauseAndReset()
        {
            var controller =
                new AgentActionController<string, int>();

            var first = new TestAction(
                "First",
                new AgentActionSettings(cooldown: 2f));

            var second = new TestAction("Second");

            controller.TryRegister(first);
            controller.TryRegister(second);

            controller.TryStartAction("First", 0);
            controller.TryStartAction("Second", 0);

            controller.SetPaused(true);
            controller.Tick(0, 1f);

            bool pausePassed =
                controller.IsPaused &&
                second.TickCount == 0 &&
                controller.TotalElapsedTime == 0d;
            Debug.Assert(pausePassed, "一時停止中の更新抑止", this);
            Check(pausePassed, "一時停止中の更新抑止");

            bool cooldownPassed =
                controller.GetCooldownRemaining(
                    "First") == 2f;
            Debug.Assert(cooldownPassed, "一時停止中のクールダウン維持", this);
            Check(cooldownPassed, "一時停止中のクールダウン維持");

            bool startPassed =
                !controller.TryStartAction(
                    "First", 0, true);
            Debug.Assert(startPassed, "一時停止中の行動開始拒否", this);
            Check(startPassed, "一時停止中の行動開始拒否");

            controller.SetPaused(false);
            controller.Tick(0, 0.5f);

            bool resumePassed =
                !controller.IsPaused &&
                second.TickCount == 1 &&
                controller.ActionElapsedTime == 0.5d;
            Debug.Assert(resumePassed, "一時停止解除後の更新", this);
            Check(resumePassed, "一時停止解除後の更新");

            controller.SetPaused(true);

            bool stopPassed =
                controller.Stop(0) &&
                !controller.HasCurrentAction;
            Debug.Assert(stopPassed, "一時停止中の強制停止", this);
            Check(stopPassed, "一時停止中の強制停止");

            controller.Reset(0);

            bool resetPassed =
                !controller.IsPaused &&
                !controller.HasCurrentAction &&
                controller.TotalElapsedTime == 0d &&
                controller.ActionElapsedTime == 0d &&
                !controller.IsOnCooldown("First") &&
                controller.Count == 2;
            Debug.Assert(resetPassed, "登録維持と実行状態初期化", this);
            Check(resetPassed, "登録維持と実行状態初期化");
        }

        /// <summary>
        /// イベント通知と例外処理を検証する。
        /// </summary>
        private void TestSafety()
        {
            var controller =
                new AgentActionController<string, int>();

            var action = new TestAction("Action");

            controller.TryRegister(action);

            bool started = false;
            bool ended = false;

            controller.ActionStarted += id =>
            {
                started =
                    id == "Action" &&
                    controller.HasCurrentAction;
            };

            controller.ActionEnded += (id, reason) =>
            {
                ended =
                    id == "Action" &&
                    !controller.HasCurrentAction &&
                    reason == AgentActionExitReason.Cancelled;
            };

            controller.TryStartAction("Action", 0);

            Debug.Assert(started, "開始イベントの状態整合性", this);
            Check(started, "開始イベントの状態整合性");

            controller.Stop(0);

            Debug.Assert(ended, "終了イベントの状態整合性", this);
            Check(ended, "終了イベントの状態整合性");

            bool invalidTimePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                    controller.Tick(0, -1f)) &&
                Throws<ArgumentOutOfRangeException>(() =>
                    controller.Tick(0, float.PositiveInfinity));
            Debug.Assert(invalidTimePassed, "不正更新時間の拒否", this);
            Check(invalidTimePassed, "不正更新時間の拒否");

            action.ThrowOnEnter = true;

            bool enterFaultPassed =
                Throws<InvalidOperationException>(() =>
                    controller.TryStartAction("Action", 0)) &&
                !controller.HasCurrentAction &&
                action.LastExitReason ==
                    AgentActionExitReason.Faulted;
            Debug.Assert(enterFaultPassed, "開始例外時の終了処理", this);
            Check(enterFaultPassed, "開始例外時の終了処理");

            action.ThrowOnEnter = false;
            action.ThrowOnTick = true;

            controller.TryStartAction("Action", 0);

            bool tickFaultPassed =
                Throws<InvalidOperationException>(() =>
                    controller.Tick(0, 0.5f)) &&
                !controller.HasCurrentAction &&
                action.LastExitReason ==
                    AgentActionExitReason.Faulted;
            Debug.Assert(tickFaultPassed, "更新例外時の終了処理", this);
            Check(tickFaultPassed, "更新例外時の終了処理");

            action.ThrowOnTick = false;
            action.ThrowOnExit = true;

            controller.TryStartAction("Action", 0);

            bool exitFaultPassed =
                Throws<InvalidOperationException>(() =>
                    controller.Stop(0)) &&
                !controller.HasCurrentAction;
            Debug.Assert(exitFaultPassed, "終了例外時の状態解除", this);
            Check(exitFaultPassed, "終了例外時の状態解除");

            action.ThrowOnExit = false;

            bool reentryBlocked = false;

            Action<string> handler = id =>
            {
                reentryBlocked =
                    Throws<InvalidOperationException>(() =>
                        controller.Stop(0));
            };

            controller.ActionStarted += handler;
            controller.TryStartAction("Action", 0);
            controller.ActionStarted -= handler;

            bool reentryPassed =
                reentryBlocked &&
                controller.HasCurrentAction;
            Debug.Assert(reentryPassed, "イベント通知中の再入防止", this);
            Check(reentryPassed, "イベント通知中の再入防止");

            var other =
                new AgentActionController<string, int>();

            var otherAction = new TestAction("Action");

            other.TryRegister(otherAction);
            other.TryStartAction("Action", 0);
            other.Tick(0, 1f);

            bool independentPassed =
                otherAction.TickCount == 1 &&
                controller.ActionElapsedTime == 0d &&
                other.ActionElapsedTime == 1d;
            Debug.Assert(independentPassed, "エージェント間の実行状態独立性", this);
            Check(independentPassed, "エージェント間の実行状態独立性");
        }

        /// <summary>
        /// 指定された処理の例外を検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力して集計する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
